import json, math, unittest, tempfile
from pathlib import Path
from model import load_payload

class TestLoadPayload(unittest.TestCase):
    def _write(self, text):
        d = tempfile.mkdtemp()
        p = Path(d) / "p.json"
        p.write_text(text, encoding="utf-8")
        return p

    def test_object_top_level(self):
        p = self._write('{"a": 1, "b": [true, null, "x"]}')
        self.assertEqual(load_payload(p), {"a": 1, "b": [True, None, "x"]})

    def test_array_top_level(self):
        p = self._write('[1, 2, 3]')
        self.assertEqual(load_payload(p), [1, 2, 3])

    def test_scalar_top_level_rejected(self):
        for text in ('1', '"x"', 'true', 'null'):
            with self.assertRaises(ValueError):
                load_payload(self._write(text))

    def test_invalid_json_rejected(self):
        with self.assertRaises(ValueError):
            load_payload(self._write('{oops'))

    def test_nested_nan_rejected(self):
        with self.assertRaises(ValueError):
            load_payload(self._write('{"a": [1, NaN]}'))

    def test_nested_infinity_rejected(self):
        with self.assertRaises(ValueError):
            load_payload(self._write('{"a": {"b": Infinity}}'))

    def test_finite_float_ok(self):
        p = self._write('{"a": 1.5, "b": -2.0}')
        self.assertEqual(load_payload(p), {"a": 1.5, "b": -2.0})

if __name__ == "__main__":
    unittest.main()
