import copy, json, unittest
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
from transform import transform

class TestTransform(unittest.TestCase):
    def test_schema_roundtrip(self):
        data = {
            "flags": [
                {"id": "f1", "variants": [{"id": "on", "attachment": {"a": 1}}],
                 "rules": [{"id": "r1", "segment": "s0", "variant": "on"}]}
            ],
            "segments": [{"id": "s0"}],
            "old_snapshot": {"flags": []},
        }
        contract = {"name": "schema", "operation": "feature_schema", "inputs": ["x"], "output": "y"}
        before = copy.deepcopy(data)
        out = transform([data], contract)
        self.assertEqual(set(out), {"name", "result"})
        self.assertEqual(out["name"], "schema")
        self.assertEqual(out["result"], {"flags": data["flags"], "segments": data["segments"]})
        self.assertEqual(data, before)

    def test_schema_duplicate_flag(self):
        data = {"flags": [{"id": "f", "variants": [], "rules": []},
                          {"id": "f", "variants": [], "rules": []}], "segments": []}
        contract = {"name": "schema", "operation": "feature_schema"}
        with self.assertRaises(ValueError):
            transform([data], contract)

    def test_attachments(self):
        data = {"flags": [{"id": "f1", "variants": [{"id": "on", "attachment": {"b": True, "n": [0, None]}}]}]}
        contract = {"name": "attachments", "operation": "feature_attachments"}
        out = transform([data], contract)
        self.assertEqual(out["result"]["attachments"]["f1"]["on"]["value"], {"b": True, "n": [0, None]})
        self.assertEqual(out["result"]["attachments"]["f1"]["on"]["canonical"],
                         json.dumps({"b": True, "n": [0, None]}, ensure_ascii=False, sort_keys=True, separators=(",", ":")))

    def test_references_ok(self):
        data = {"flags": [{"id": "f1", "variants": [{"id": "on"}],
                           "rules": [{"id": "r1", "segment": "s0", "variant": "on"}]}],
                "segments": [{"id": "s0"}]}
        contract = {"name": "references", "operation": "feature_references"}
        out = transform([data], contract)
        self.assertEqual(out["result"], {"ok": True, "error": None})

    def test_references_missing_segment(self):
        data = {"flags": [{"id": "f1", "variants": [{"id": "on"}],
                           "rules": [{"id": "r1", "segment": "sX", "variant": "on"}]}],
                "segments": [{"id": "s0"}]}
        contract = {"name": "references", "operation": "feature_references"}
        out = transform([data], contract)
        self.assertEqual(out["result"], {"ok": False, "error": {"kind": "segment", "flag": "f1", "rule": "r1", "target": "sX"}})

    def test_snapshot_committed(self):
        original = {"old_snapshot": {"flags": []}}
        schema = {"flags": [{"id": "f1", "variants": [{"id": "on"}],
                             "rules": [{"id": "r1", "segment": "s0", "variant": "on"}]}],
                  "segments": [{"id": "s0"}]}
        attachments = {"attachments": {"f1": {"on": {"value": {"x": 1}, "canonical": "{\"x\":1}"}}}}
        references = {"ok": True, "error": None}
        contract = {"name": "snapshot", "operation": "feature_snapshot"}
        out = transform([original, schema, attachments, references], contract)
        self.assertTrue(out["result"]["committed"])
        self.assertEqual(out["result"]["snapshot"]["flags"][0]["variants"][0]["attachment"], {"x": 1})
        self.assertIsNone(out["result"]["error"])

    def test_snapshot_rollback(self):
        original = {"old_snapshot": {"flags": [{"id": "old"}]}}
        schema = {"flags": [], "segments": []}
        attachments = {"attachments": {}}
        references = {"ok": False, "error": {"kind": "segment", "flag": "f", "rule": "r", "target": "s"}}
        contract = {"name": "snapshot", "operation": "feature_snapshot"}
        out = transform([original, schema, attachments, references], contract)
        self.assertFalse(out["result"]["committed"])
        self.assertEqual(out["result"]["snapshot"], {"flags": [{"id": "old"}]})
        self.assertIsNone(out["result"]["export"])

if __name__ == "__main__":
    unittest.main()
